import JSON

"""
	ellipk( m )

Evaluate the complete elliptic integral of the first kind in extended precision.

# Arguments

* `m`: parameter

# Examples

``` julia
julia> y = ellipk( BigFloat( -1.0 ) );
```
"""
function ellipk( m )
	# Use `K(m) = π / ( 2 * agm( 1, sqrt(1-m) ) )`, which holds for all `m < 1` without transforming a negative `m` into a parameter close to one:
	a = BigFloat( 1 );
	b = sqrt( 1 - m );
	while abs( a - b ) > eps( a ) * 4
		a, b = ( a + b ) / 2, sqrt( a * b );
	end
	return BigFloat( pi ) / ( a + b );
end

"""
	gen( x, name )

Generate fixture data and write to file.

# Arguments

* `x`: input values
* `name::AbstractString`: output filename

# Examples

``` julia
julia> x = -rand( 1000 ) .* 1.0e10;
julia> gen( x, "data.json" );
```
"""
function gen( x, name )
	y = setprecision( BigFloat, 2048 ) do
		Float64.( ellipk.( BigFloat.( x ) ) );
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("x", x),
		("expected", y)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Large negative values:
x = -( rand( 4000 ) .* ( 1.0e10 - 1.0 ) .+ 1.0 );
gen( x, "large_negative.json" );

# Huge negative values (below `-2^53`, `m/(m-1)` rounds to one):
x = -exp10.( range( 10.0, stop = 300.0, length = 1000 ) );
gen( x, "huge_negative.json" );
